// /status, /retry, /new, rules and member commands, well-formed A1 / storyboard / A2 / intake /
// member / A3 / cleanup buttons, and replies with notes to a storyboard, A2 or A3 request reach the
// database; anything else is ignored. Storyboard requests (WF-12) end with "ref:<token>".
const update = $input.first().json;
// /status [video id prefix] (P-017) is answered from telegram_status(); approvers only.
const statusCommand = /^\/status(?:@\w+)?(?:\s+([0-9a-fA-F-]{1,36}))?\s*$/.exec(update.message?.text ?? '');
if (update.message && statusCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'status',
      prefix: (statusCommand[1] ?? '').toLowerCase(),
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// /retry <video id prefix> (D-056) gives a permanently failed job one more attempt; approvers only.
const retryCommand = /^\/retry(?:@\w+)?\s+([0-9a-fA-F-]{4,36})\s*$/.exec(update.message?.text ?? '');
if (update.message && retryCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'retry',
      prefix: retryCommand[1].toLowerCase(),
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// Channel rules (D-059): /rules [video|tts|say], /rules file <scope>, a .md/.txt file captioned
// /rules set <scope>, /rule add <video|tts> <text>, /rule del <number>, /say <term> = <spoken>,
// /unsay <term>. telegram_rules() checks the user.
const rulesText = update.message?.text ?? update.message?.caption ?? '';
const rulesCommand = /^\/(rules|rule|say|unsay)(?:@\w+)?(?=\s|$)([\s\S]*)$/.exec(rulesText);
if (update.message && rulesCommand && !update.message.from?.is_bot) {
  const message = update.message;
  const base = {
    kind: 'rules',
    userId: String(message.from.id),
    chatId: String(message.chat.id),
    messageId: String(message.message_id),
    scope: '',
    text: '',
    extra: '',
    fileId: '',
    exportFile: false,
    error: '',
  };
  const scopes = { video: 'video', tts: 'tts', say: 'pronunciation' };
  const usage = 'Cách dùng: /rules [video|tts|say] · /rules file <video|tts|say> · /rule add <video|tts> <nội dung> · /rule del <số> · /say <từ> = <cách đọc> · /unsay <từ> · gửi file .md/.txt kèm caption /rules set <video|tts|say>';
  const out = (fields) => [{ json: { ...base, ...fields } }];
  const [, command, restRaw] = rulesCommand;
  const rest = restRaw.trim();
  if (command === 'rules') {
    const parts = rest.split(/\s+/).filter(Boolean);
    if (parts.length === 0) return out({ action: 'VIEW' });
    if (parts.length === 1 && scopes[parts[0]]) return out({ action: 'VIEW', scope: scopes[parts[0]] });
    if (parts.length === 2 && parts[0] === 'file' && scopes[parts[1]]) {
      return out({ action: 'VIEW', scope: scopes[parts[1]], exportFile: true });
    }
    if (parts.length === 2 && parts[0] === 'set' && scopes[parts[1]]) {
      const file = message.document;
      if (!file) return out({ error: 'Hãy đính kèm file .md hoặc .txt đã sửa, với caption /rules set <video|tts|say>.' });
      if (!/\.(md|txt)$/i.test(file.file_name ?? '') || (file.file_size ?? 0) > 200000) {
        return out({ error: 'Quy tắc phải là file .md hoặc .txt, tối đa 200 KB.' });
      }
      return out({ action: 'SET', scope: scopes[parts[1]], fileId: file.file_id });
    }
    return out({ error: usage });
  }
  if (command === 'rule') {
    const add = /^add\s+(video|tts)\s+([\s\S]+)$/.exec(rest);
    if (add) return out({ action: 'ADD', scope: add[1], text: add[2].trim() });
    const del = /^del\s+#?(\d{1,18})$/.exec(rest);
    if (del) return out({ action: 'DELETE', text: del[1] });
    return out({ error: usage });
  }
  if (command === 'say') {
    const say = /^([^=\n]+?)\s*=\s*(.+)$/.exec(rest);
    if (say) return out({ action: 'SAY', scope: 'pronunciation', text: say[1].trim(), extra: say[2].trim() });
    return out({ error: usage });
  }
  if (rest === '' || rest.includes('\n')) return out({ error: usage });
  return out({ action: 'UNSAY', scope: 'pronunciation', text: rest });
}
// /new [minutes] <topic> (D-058), notes on the next lines, optionally as the caption of a .md/.txt
// file holding the full brief. Only in the approval chat; telegram_intake_draft() checks the user.
const APPROVAL_CHAT = 'REPLACE_WITH_APPROVAL_CHAT_ID';
// Members (D-060): /join asks the owner (in the approval chat only), /members lists approvers,
// /revoke <user id> is the owner's. telegram_members() checks who may do what.
const memberCommand = /^\/(join|members|revoke)(?:@\w+)?(?=\s|$)([\s\S]*)$/.exec(update.message?.text ?? '');
if (update.message && memberCommand && !update.message.from?.is_bot) {
  const message = update.message;
  const from = message.from;
  const base = {
    kind: 'member',
    userId: String(from.id),
    chatId: String(message.chat.id),
    messageId: String(message.message_id),
    name: '',
    target: '',
    error: '',
    text: '',
  };
  const fail = (error) => [{ json: { ...base, error, text: error } }];
  const [, command, rest] = memberCommand;
  if (command === 'join') {
    if (String(message.chat.id) !== APPROVAL_CHAT) {
      return fail(`Chat này (${message.chat.id}) không phải chat duyệt; /join chỉ dùng được ở đó.`);
    }
    const name = from.username ? `@${from.username}` : [from.first_name, from.last_name].filter(Boolean).join(' ');
    return [{ json: { ...base, action: 'JOIN', name } }];
  }
  if (command === 'members') return [{ json: { ...base, action: 'LIST' } }];
  const target = rest.trim();
  if (!/^\d{1,18}$/.test(target)) return fail('Cách dùng: /revoke <user id> (xem id bằng /members)');
  return [{ json: { ...base, action: 'REVOKE', target } }];
}
const newCommand = /^\/new(?:@\w+)?(?=\s|$)([\s\S]*)$/.exec(update.message?.text ?? update.message?.caption ?? '');
if (update.message && newCommand && !update.message.from?.is_bot) {
  const message = update.message;
  const base = {
    kind: 'intake',
    userId: String(message.from.id),
    chatId: String(message.chat.id),
    messageId: String(message.message_id),
  };
  const fail = (error) => [{ json: { ...base, error } }];
  if (String(message.chat.id) !== APPROVAL_CHAT) {
    return fail(`Chat này (${message.chat.id}) không phải chat duyệt; /new chỉ dùng được ở đó.`);
  }
  const [first = '', ...rest] = newCommand[1].trim().split('\n');
  const minutes = /^(\d{1,2})\s+(\S[\s\S]*)$/.exec(first.trim());
  const topic = (minutes ? minutes[2] : first).trim();
  if (topic === '') {
    return fail('Cách dùng: /new [số phút] <chủ đề>, ghi chú ở các dòng sau; full brief thì gửi file .md hoặc .txt với lệnh này làm caption.');
  }
  const file = message.document;
  if (file && (!/\.(md|txt)$/i.test(file.file_name ?? '') || (file.file_size ?? 0) > 200000)) {
    return fail('Full brief phải là file .md hoặc .txt, tối đa 200 KB.');
  }
  return [{
    json: {
      ...base,
      topic,
      minutes: minutes ? Number(minutes[1]) : null,
      notes: rest.join('\n').trim(),
      fileId: file?.file_id ?? '',
      error: '',
    },
  }];
}
const query = update.callback_query;
const actions = { A: 'APPROVE', G: 'REGENERATE', R: 'REJECT' };
if (query) {
  const match = /^(a1|sb|a2|in|mb|a3|cl):([AGR]):([0-9a-f]{32})$/.exec(query.data ?? '');
  if (!match || (!['a1', 'a3'].includes(match[1]) && match[2] === 'G')) return [];
  return [{
    json: {
      kind: 'button',
      approval: { a1: 'script', sb: 'storyboard', a2: 'preview', in: 'intake', mb: 'member', a3: 'metadata', cl: 'cleanup' }[match[1]],
      queryId: query.id,
      userId: String(query.from.id),
      chatId: String(query.message?.chat?.id ?? ''),
      messageId: String(query.message?.message_id ?? ''),
      originalText: String(query.message?.text ?? ''),
      action: actions[match[2]],
      token: match[3],
      note: '',
    },
  }];
}
const message = update.message;
const repliedTo = message?.reply_to_message;
// A3 messages (D-062) end with meta:<token> instead, so notes there rewrite the metadata.
const ref = /(ref|meta):([0-9a-f]{32})/.exec(repliedTo?.text ?? '');
if (!message || message.from?.is_bot || !repliedTo?.from?.is_bot || !ref || typeof message.text !== 'string') return [];
return [{
  json: {
    kind: 'reply',
    approval: ref[1] === 'meta' ? 'metadata' : 'storyboard',
    userId: String(message.from.id),
    chatId: String(message.chat.id),
    messageId: String(message.message_id),
    action: 'FEEDBACK',
    token: ref[2],
    note: message.text.trim(),
  },
}];

// telegram_decide() result codes -> short replies. Buttons are removed once the request is
// settled (decided, superseded, expired); a refused stranger leaves the message untouched. Replies
// with notes (storyboard or A2) are answered in the chat; both revise the storyboard.
const input = $('Parse callback').first().json;
const { result, version, round, video_id: videoId } = $input.first().json;
const storyboard = input.approval === 'storyboard';
const preview = input.approval === 'preview';
const intake = input.approval === 'intake';
const member = input.approval === 'member';
const metadata = input.approval === 'metadata';
const cleanup = input.approval === 'cleanup';
const notes = `Đã nhận ghi chú: đang sửa storyboard (vòng ${round}/4).`;
const done = cleanup
  ? {
      APPROVE: 'Đã duyệt: kiểm tra lại bản lưu trên Google Drive rồi xóa bản trên Mac.',
      REJECT: 'Giữ lại bản trên Mac.',
    }
  : metadata
  ? {
      APPROVE: 'Đã duyệt: đang lưu trữ lên Google Drive để hoàn tất video.',
      REGENERATE: `Đang viết lại metadata (lần ${round}).`,
      FEEDBACK: `Đã nhận ghi chú: đang viết lại metadata (lần ${round}).`,
    }
  : member
  ? { APPROVE: 'Đã duyệt: người này giờ là approver.', REJECT: 'Đã từ chối: không thêm người này.' }
  : intake
  ? {
      APPROVE: `Đã tạo video ${String(videoId).slice(0, 8)}: đang viết kịch bản, yêu cầu duyệt A1 sẽ đến sau.`,
      REJECT: 'Đã hủy, không tạo gì.',
    }
  : storyboard
  ? { APPROVE: 'Đã duyệt: đang render preview', REJECT: 'Đã từ chối (hủy video)', FEEDBACK: notes }
  : preview
    ? { APPROVE: 'Đã duyệt: đang render bản cuối 1080p', REJECT: 'Đã từ chối (hủy video)' }
    : { APPROVE: 'Đã duyệt', REJECT: 'Đã từ chối (hủy video)', REGENERATE: `Đang viết lại thành v${version}` };
const replies = {
  OK: done[input.action],
  NOT_ALLOWED: 'Bạn không phải approver.',
  NOT_OWNER: cleanup ? 'Chỉ chủ sở hữu mới xóa được bản trên Mac.' : 'Chỉ chủ sở hữu mới duyệt được thành viên mới.',
  NOT_FOUND: 'Không tìm thấy yêu cầu duyệt này.',
  NOT_PENDING: 'Đã được quyết định rồi.',
  EXPIRED: 'Yêu cầu này đã hết hạn.',
  SUPERSEDED: 'Đã có phiên bản mới hơn; yêu cầu này không còn hiệu lực.',
  HASH_MISMATCH: `${storyboard ? 'Storyboard' : preview ? 'Preview' : metadata ? 'Metadata' : 'Kịch bản'} đã thay đổi sau khi gửi yêu cầu; hãy chờ yêu cầu mới.`,
  EMPTY_NOTE: 'Hãy viết ghi chú trong nội dung trả lời.',
  NOT_SUPPORTED: 'Không áp dụng được cho yêu cầu này.',
  NEEDS_DECISION: 'Đó là vòng ghi chú cuối; video cần bạn quyết định.',
};
const settled = ['OK', 'NOT_PENDING', 'EXPIRED', 'SUPERSEDED', 'NEEDS_DECISION'].includes(result);
const decidedAt = new Date().toISOString().replace('T', ' ').slice(0, 16);
const answer = replies[result] ?? `Không áp dụng được (${result}).`;
return [{
  json: {
    answer,
    settled,
    isButton: input.kind !== 'reply',
    chatId: input.chatId,
    messageId: input.messageId,
    queryId: input.queryId,
    editedText: `${input.originalText}\n\n${result === 'OK' ? 'Quyết định' : 'Đã đóng'}: ${answer} (${decidedAt} UTC)`.slice(0, 4096),
  },
}];

// telegram_status() rows -> one status message (P-017). Telegram text is Vietnamese (D-061). Times are minutes since the step or job started.
const input = $('Parse callback').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row.allowed !== undefined);
const reply = (text) => [{ json: { text: text.slice(0, 4096), chatId: input.chatId, messageId: input.messageId } }];
if (rows.some((row) => row.allowed === false)) return reply('Bạn không phải approver.');
if (rows.length === 0) {
  return reply(input.prefix ? `[AI Video] Không có video nào có id bắt đầu bằng ${input.prefix}.` : '[AI Video] Không có video nào đang chạy.');
}
const minutes = (from, to = Date.now()) => {
  const m = Math.max(0, Math.round((new Date(to).getTime() - new Date(from).getTime()) / 60_000));
  return m < 60 ? `${m} phút` : `${Math.floor(m / 60)} giờ ${String(m % 60).padStart(2, '0')} phút`;
};
const describe = (p) => {
  if (!p || !p.stage) return '';
  const turn = p.turn ? ` ${p.turn}/${p.of}` : '';
  switch (p.stage) {
    case 'agent': return `agent lượt${turn}`;
    case 'gates': return `đang kiểm tra (lượt${turn})`;
    case 'tts': return `lời đọc ${p.scene}/${p.of}`;
    case 'voice': return 'đang ghép giọng';
    case 'whisper': return 'whisper';
    case 'render': return `đang render ${p.frames ?? ''} khung hình`.replace('  ', ' ');
    case 'loudness': return 'chuẩn hóa âm lượng';
    case 'qa': return 'QA';
    case 'metadata': return `viết metadata (lần ${p.round ?? 1})`;
    case 'archive': return p.step === 'uploading' ? 'đang tải lên bản lưu' : 'đang gom file';
    case 'cleanup': return p.step === 'deleting' ? 'đang xóa bản trên Mac' : 'đang kiểm tra lại bản lưu';
    default: return String(p.stage);
  }
};
const head = (row) => `${String(row.video_id).slice(0, 8)} v${row.version} · ${row.title ?? '?'}`;
// telegram_status() says "<type> until <time> UTC".
const approval = (row) => String(row.approval).replace(' until ', ', hạn ');
const cost = (row) => Object.entries(row.cost ?? {}).map(([c, v]) => `${Math.round(v * 100) / 100} ${c}`).join(', ');

if (input.prefix) {
  const row = rows[0];
  const marks = { SUCCEEDED: '✓', RUNNING: '▶', FAILED_PERMANENT: '✗', FAILED_RETRYABLE: '↻', BLOCKED: '⏸' };
  const jobs = (row.jobs ?? []).map((job) => {
    const parts = [`${marks[job.status] ?? '·'} ${job.step}`];
    if (job.started) parts.push(minutes(job.started, job.status === 'RUNNING' ? undefined : job.finished ?? undefined));
    else parts.push('đang chờ');
    if (job.attempts > 1) parts.push(`${job.attempts} lần chạy`);
    if (job.status === 'RUNNING' && describe(job.progress)) parts.push(describe(job.progress));
    if (job.error && job.status !== 'SUCCEEDED') parts.push(job.error);
    return parts.join(' · ');
  });
  return reply([
    `[AI Video] Video ${head(row)}`,
    `Trạng thái: ${row.status} (${minutes(row.status_since)})`,
    ...jobs,
    cost(row) ? `Chi phí: ${cost(row)}` : 'Chi phí: chưa ghi nhận',
    ...(row.approval ? [`Đang chờ: ${approval(row)}`] : []),
    ...(row.status === 'NEEDS_DECISION' ? [`Chạy lại bước lỗi: /retry ${String(row.video_id).slice(0, 8)}`] : []),
  ].join('\n'));
}

const lines = rows.flatMap((row) => {
  const step = row.step
    ? `${row.step} ${String(row.step_status).toLowerCase()} ${minutes(row.step_since)}`
    : 'chưa có job';
  const extra = [describe(row.progress), `${row.steps_done}/${row.steps_total} job xong`, row.approval ? `chờ ${approval(row)}` : '']
    .filter(Boolean);
  return ['', head(row), [row.status, step, ...extra].join(' · ')];
});
return reply([`[AI Video] ${rows.length} video đang chạy`, ...lines, '', 'Chi tiết: /status <8 ký tự đầu của id>'].join('\n'));

// telegram_retry() result -> one reply (D-056). Telegram text is Vietnamese (D-061).
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const id = row.video_id ? String(row.video_id).slice(0, 8) : input.prefix;
const texts = {
  RETRIED: `[AI Video] Đang chạy lại bước ${row.step} của video ${id} (lần ${row.attempt}). Tiến độ: /status ${id}`,
  NOT_APPROVER: 'Bạn không phải approver.',
  NOT_FOUND: `[AI Video] Không có video nào có id bắt đầu bằng ${input.prefix}.`,
  AMBIGUOUS: `[AI Video] Có nhiều video có id bắt đầu bằng ${input.prefix}; hãy gõ thêm ký tự.`,
  NOT_STOPPED: `[AI Video] Video ${id} không ở trạng thái chờ quyết định; không có gì để chạy lại.`,
  NO_FAILED_JOB: `[AI Video] Video ${id} không có job lỗi nào để chạy lại.`,
};
const text = texts[row.result] ?? `[AI Video] Không chạy lại được: ${row.result ?? 'không có phản hồi'}.`;
return [{ json: { text, chatId: input.chatId, messageId: input.messageId } }];

// /new -> the brief for telegram_intake_draft() (D-058); a parse error becomes the reply instead.
// The full brief file is read as UTF-8 text and kept verbatim (only a byte order mark is dropped).
const input = $('Parse callback').first().json;
const reply = { chatId: input.chatId, messageId: input.messageId };
if (input.error) return [{ json: { ...reply, ok: false, text: input.error } }];
const fullBrief = input.fileId
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8').replace(/^\uFEFF/, '')
  : '';
const brief = {
  topic: input.topic,
  ...(input.minutes ? { duration_minutes: input.minutes } : {}),
  ...(fullBrief.trim() ? { full_brief: fullBrief } : {}),
  ...(input.notes ? { notes: input.notes } : {}),
};
return [{ json: { ...reply, ok: true, userId: input.userId, brief: JSON.stringify(brief) } }];

// telegram_intake_draft() -> the confirmation with Create / Cancel (callback in:<A|R>:<token>), or
// the reason nothing was drafted. Telegram text is Vietnamese (D-061).
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const reply = { chatId: input.chatId, messageId: input.messageId };
if (row.result === 'NOT_APPROVER') return [{ json: { ...reply, text: 'Bạn không phải approver.' } }];
if (row.result !== 'DRAFT') {
  return [{ json: { ...reply, text: `[AI Video] Chưa tạo: ${row.error ?? row.result ?? 'không có phản hồi'}` } }];
}
const brief = typeof row.brief === 'string' ? JSON.parse(row.brief) : row.brief;
const text = [
  '[AI Video] Tập mới: xác nhận',
  `Chủ đề: ${brief.topic}`,
  `Thời lượng: ${brief.duration_minutes ? `khoảng ${brief.duration_minutes} phút` : 'không đặt (khoảng 6 phút)'}`,
  `Full brief: ${brief.full_brief ? `${brief.full_brief.length} ký tự` : 'không có (Claude tự viết tập)'}`,
  ...(brief.notes ? [`Ghi chú: ${brief.notes}`] : []),
  ...(row.has_voice === false
    ? ['', 'Cảnh báo: full brief không có mục VOICE. Khi có full brief, kịch bản phải chép nguyên văn từng câu thoại từ đó, nên brief này sẽ lỗi. Hãy thêm mục VOICE, hoặc gửi dàn ý dưới dạng ghi chú.']
    : []),
  '',
  `Hết hạn: ${new Date(row.expires_at).toISOString().replace('T', ' ').slice(0, 16)} UTC`,
].join('\n');
return [{ json: { ...reply, text, approve: `in:A:${row.token}`, reject: `in:R:${row.token}` } }];

// A rules command -> the arguments of telegram_rules() (D-059); a usage error becomes the reply.
// A /rules set file is read as UTF-8 (a byte order mark is dropped).
const input = $('Parse callback').first().json;
const reply = { chatId: input.chatId, messageId: input.messageId };
if (input.error) return [{ json: { ...reply, ok: false, text: input.error } }];
const text = input.fileId
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8').replace(/^\uFEFF/, '')
  : input.text;
return [{
  json: {
    ...reply,
    ok: true,
    userId: input.userId,
    action: input.action,
    scope: input.scope,
    text,
    extra: input.extra,
  },
}];

// telegram_rules() -> the reply (D-059): the rules list, a confirmation, a refusal, or a Markdown
// file to edit (/rules file). Telegram text is Vietnamese (D-061).
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const reply = { chatId: input.chatId, messageId: input.messageId };
const say = (text) => [{ json: { ...reply, exportFile: false, text: text.slice(0, 4096) } }];
if (row.result === 'NOT_APPROVER') return say('Bạn không phải approver.');
if (row.result === 'INVALID') return say(`[AI Video] Chưa thay đổi: ${row.detail}`);
if (row.result === 'NOT_FOUND') {
  return say(input.action === 'DELETE' ? `[AI Video] Không có quy tắc #${row.detail}.` : `[AI Video] Chưa có cách đọc cho "${row.detail}".`);
}
if (row.result !== 'OK') return say(`[AI Video] Quy tắc: ${row.result ?? 'không có phản hồi'}`);
const rules = typeof row.rules === 'string' ? JSON.parse(row.rules) : row.rules;
const names = { video: 'video', tts: 'TTS', pronunciation: 'phát âm' };
const items = (scope) =>
  scope === 'pronunciation'
    ? rules.pronunciation.map((p) => `${p.term} = ${p.spoken}`)
    : rules[scope].map((r) => `#${r.id} ${r.text}`);
if (input.exportFile) {
  const scope = input.scope;
  const header = scope === 'pronunciation'
    ? ['# Phát âm', '', 'Mỗi mục là một dòng "từ = cách đọc" (phân biệt hoa thường, khớp nguyên từ); các dòng khác bị bỏ qua.']
    : [`# Quy tắc ${names[scope]}`, '', 'Mỗi mục danh sách là một quy tắc; các dòng khác bị bỏ qua.'];
  const list = scope === 'pronunciation' ? items(scope) : rules[scope].map((r) => r.text);
  return [{
    json: {
      ...reply,
      exportFile: true,
      fileName: `${scope === 'pronunciation' ? 'say' : scope}-rules.md`,
      markdown: [...header, '', ...list.map((item) => `- ${item}`), ''].join('\n'),
      caption: `Sửa xong gửi lại với caption /rules set ${scope === 'pronunciation' ? 'say' : scope}`,
    },
  }];
}
const done = {
  ADD: () => `[AI Video] Đã thêm quy tắc #${row.detail} (${names[input.scope]}).`,
  DELETE: () => `[AI Video] Đã xóa quy tắc #${input.text}.`,
  SET: () => `[AI Video] Đã thay toàn bộ quy tắc ${names[input.scope]}: giờ có ${rules[input.scope].length} mục.`,
  SAY: () => `[AI Video] "${input.text}" giờ được đọc là "${input.extra}".`,
  UNSAY: () => `[AI Video] "${input.text}" lại được đọc như chữ viết.`,
}[input.action];
if (done) return say(`${done()} Áp dụng cho các bước bắt đầu từ bây giờ.`);
const scopes = input.scope ? [input.scope] : ['video', 'tts', 'pronunciation'];
const lines = scopes.flatMap((scope) => ['', `${names[scope][0].toUpperCase()}${names[scope].slice(1)}:`, ...(items(scope).length ? items(scope) : ['(chưa có)'])]);
const text = [`[AI Video] Quy tắc kênh (phiên bản ${String(rules.version).slice(0, 8)})`, ...lines, '', 'Sửa: /rule add video|tts <nội dung> · /rule del <số> · /say <từ> = <cách đọc> · /unsay <từ> · /rules file video|tts|say'].join('\n');
return say(text.length > 4096 ? `${text.slice(0, 3900)}\n…\nQuá dài cho một tin nhắn: dùng /rules file video|tts|say.` : text);

// The rules as a Markdown file for /rules file (D-059).
const row = $input.first().json;
const data = await this.helpers.prepareBinaryData(Buffer.from(row.markdown, 'utf8'), row.fileName, 'text/markdown');
return [{ json: { chatId: row.chatId, messageId: row.messageId, caption: row.caption }, binary: { data } }];

// telegram_members() -> the reply (D-060): a join request for the owner with Approve / Reject
// (callback mb:<A|R>:<token>), the approver list, or why nothing changed. Telegram text is Vietnamese (D-061).
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const reply = { chatId: input.chatId, messageId: input.messageId };
const say = (text) => [{ json: { ...reply, text } }];
const list = (members) => {
  const rows = typeof members === 'string' ? JSON.parse(members) : members ?? [];
  return [
    `[AI Video] Approver (${rows.length})`,
    ...rows.map((m) => `${m.owner ? '★' : '-'} ${m.name} (id ${m.user_id})${m.owner ? ' · chủ sở hữu' : ''}`),
    '',
    'Chủ sở hữu có thể gỡ một người bằng /revoke <user id>.',
  ].join('\n');
};
switch (row.result) {
  case 'REQUESTED':
    return [{
      json: {
        ...reply,
        text: [
          `[AI Video] ${input.name} (id ${input.userId}) xin làm approver.`,
          'Chỉ chủ sở hữu mới duyệt được. Yêu cầu hết hạn sau 72 giờ.',
        ].join('\n'),
        approve: `mb:A:${row.token}`,
        reject: `mb:R:${row.token}`,
      },
    }];
  case 'ALREADY_MEMBER': return say('Bạn đã là approver rồi.');
  case 'ALREADY_REQUESTED': return say('Yêu cầu của bạn đang chờ chủ sở hữu duyệt.');
  case 'NO_OWNER': return say('[AI Video] Chưa đặt chủ sở hữu nên chưa ai duyệt được thành viên mới.');
  case 'NOT_APPROVER': return say('Bạn không phải approver.');
  case 'NOT_OWNER': return say('Chỉ chủ sở hữu mới làm được việc này.');
  case 'NOT_FOUND': return say(`[AI Video] ${row.detail} không phải approver.`);
  case 'INVALID': return say(`[AI Video] Chưa thay đổi: ${row.detail}`);
  case 'OK':
    return say(input.action === 'REVOKE' ? `[AI Video] ${row.detail} không còn là approver.\n\n${list(row.members)}` : list(row.members));
  default: return say(`[AI Video] Thành viên: ${row.result ?? 'không có phản hồi'}`);
}
